# /// script
# requires-python = ">=3.11"
# dependencies = ["beautifulsoup4", "lxml", "pillow"]
# ///
"""Convert an arXiv paper's HTML version (arxiv.org/html/<id>, generated by LaTeXML) into a paper-reader page.

    uv run arxiv.py 2501.14926 [--out DIR]

Writes DIR/index.html, DIR/figures/ and DIR/batches.json (default DIR: ./arxiv-<id>/out).
Math is rendered in the browser by KaTeX from each equation's TeX source (LaTeXML's alttext);
an equation KaTeX can't parse keeps LaTeXML's MathML, which browsers render natively.
"""
import argparse, re, sys
from concurrent.futures import ThreadPoolExecutor
from pathlib import Path
from urllib.parse import urljoin
from bs4 import BeautifulSoup, NavigableString

sys.path.insert(0, str(Path(__file__).parent))
from common import download, figure_tone, fill, get, write_batches

ap = argparse.ArgumentParser()
ap.add_argument("paper", help="arXiv id (2501.14926, 2501.14926v2) or an arxiv.org abs/html/pdf URL")
ap.add_argument("--out", type=Path)
args = ap.parse_args()
pid = re.search(r"(\d{4}\.\d{4,5}(v\d+)?)", args.paper).group(1)
OUT = args.out or Path(f"arxiv-{pid}") / "out"

resp = get(f"https://arxiv.org/html/{pid}")
page_url = resp.geturl()
soup = BeautifulSoup(resp.read(), "lxml")
art = soup.select_one("article.ltx_document")
if art is None:
    sys.exit(f"No HTML version for {pid} (arXiv only has HTML for papers whose LaTeX converted cleanly); use the PDF.")
version = re.search(r"\d{4}\.\d{4,5}v\d+", str(art.select_one("img, object") or "") + page_url)
version = version.group(0) if version else pid

def new(tag, cls=None, **attrs):
    t = soup.new_tag(tag, **attrs)
    if cls: t["class"] = cls
    return t

def text(el):
    return re.sub(r"\s+", " ", el.get_text(" ", strip=True)).strip()

# ---- front matter: title, authors, abstract
title_el = art.select_one(".ltx_title_document")
for n in title_el.select(".ltx_note"): n.decompose()
title = text(title_el)

names, affils, thanks = [], [], {}
for cr in art.select(".ltx_creator.ltx_role_author"):
    for note in cr.select(".ltx_note.ltx_role_thanks"):
        mark = text(note.select_one(".ltx_note_mark"))
        body = note.select_one(".ltx_note_content")
        for x in body.select(".ltx_note_mark, .ltx_note_type"): x.decompose()
        thanks[mark] = text(body)
    marks = ",".join(text(m) for m in cr.select(".ltx_note > .ltx_note_mark"))
    for n in cr.select(".ltx_note"): n.decompose()
    person = cr.select_one(".ltx_personname") or cr
    for br in person.find_all("br"): br.replace_with("\n")
    lines = [l.strip() for l in person.get_text().split("\n") if l.strip()]
    if lines:
        names.append(lines[0] + (f"<sup>{marks}</sup>" if marks else ""))
        affils += [l for l in lines[1:] if l not in affils]
byline = f'<p class="authors">{", ".join(names)}</p>'
if affils: byline += f'<p class="affil">{" · ".join(affils)}</p>'
if thanks: byline += '<p class="affil">' + " · ".join(f"<sup>{m}</sup>{t}" for m, t in thanks.items()) + "</p>"
byline += (f'<p class="affil">Reading copy of arXiv:{version}. Original: '
           f'<a href="https://arxiv.org/abs/{version}">arxiv.org/abs/{version}</a></p>')

abstract = art.select_one(".ltx_abstract")
abs_html = ""
if abstract:
    h = abstract.select_one(".ltx_title_abstract")
    if h: h.decompose()
    abs_html = f'<div class="abstract"><span class="label">Abstract</span>{"".join(map(str, abstract.contents))}</div>'
    abstract.decompose()

# .ltx_ERROR: LaTeX commands LaTeXML could not convert, shown raw (e.g. \\abstractpagebreak)
for el in art.select(".ltx_title_document, .ltx_authors, .ltx_dates, nav.ltx_TOC, .ltx_page_footer, .ltx_keywords, .ltx_classification, .ltx_ERROR"):
    el.decompose()

# ---- bibliography: moved to the end notes; entries preview in popovers
bib_html = ""
bib = art.select_one("section.ltx_bibliography")
if bib:
    for li in bib.select("li.ltx_bibitem"):
        li["class"] = li.get("class", []) + ["poppable"]
    lst = bib.select_one("ul, ol")
    bib_html = f'<section class="endnotes" id="references"><h2>References</h2>{lst}</section>'
    bib.decompose()

# ---- footnotes: superscript links in the text, contents in the end notes
fns = []
for note in art.select(".ltx_note.ltx_role_footnote"):
    content = note.select_one(".ltx_note_content")
    for x in content.select(".ltx_note_mark, .ltx_tag_note"): x.decompose()
    n = len(fns) + 1
    li = new("li", ["poppable"], id=f"fn-{n}")
    li.extend(list(content.contents))
    fns.append(li)
    sup = new("sup", ["fn"]); a = new("a", href=f"#fn-{n}"); a.string = str(n); sup.append(a)
    note.replace_with(sup)
for note in art.select(".ltx_note"):  # leftover footnote marks and margin notes
    note.decompose()
fn_html = (f'<section class="endnotes" id="footnotes"><h2>Footnotes</h2><ol>{"".join(map(str, fns))}</ol></section>' if fns else "")

# ---- equations: LaTeXML's equation tables become compact left-aligned rows with the number on the right
for tbl in art.select("table.ltx_equation, table.ltx_equationgroup"):
    eq = new("table", ["eq", "poppable"]); eq["id"] = tbl.get("id", "")
    if not eq["id"]: del eq["id"]
    for tr in tbl.select("tr.ltx_eqn_row"):
        row = new("tr")
        if tr.get("id"): row["id"] = tr["id"]
        row.append(new("td", ["fill"]))
        no = None
        for td in tr.find_all("td", recursive=False):
            cls = td.get("class", [])
            if "ltx_eqn_eqno" in cls:
                no = td; continue
            if any(c in cls for c in ("ltx_eqn_center_padleft", "ltx_eqn_center_padright")) or not td.get_text(strip=True) and not td.find("math"):
                continue
            cell = new("td", ["r" if "ltx_align_right" in cls else "l"])
            cell.extend(list(td.contents)); row.append(cell)
        row.append(new("td", ["fill"]))
        num = new("td", ["eq-no"]); num.string = text(no) if no else ""; row.append(num)
        eq.append(row)
    tbl.replace_with(eq)

for m in art.find_all("math"):
    tex = m.get("alttext")
    if not tex: continue
    wrap = new("span", **{"data-tex": tex, "data-display": "1" if m.get("display") == "block" else "0"})
    m.replace_with(wrap); wrap.append(m)
    for a in m.find_all("annotation"): a.decompose()
    # keep punctuation that follows inline math on the same line, e.g. "$x$)."
    nxt = wrap.next_sibling
    if wrap["data-display"] == "0" and isinstance(nxt, NavigableString) and (p := re.match(r"[)\].,;:!?’”']+", str(nxt))):
        keep = new("span", ["nowrap"]); wrap.wrap(keep); keep.append(p.group(0))
        nxt.replace_with(str(nxt)[p.end():])

# ---- figures and tables: images downloaded; figures, tables preview in popovers
assets, imgs = {}, {}
for el in art.select("img[src], object[data]"):
    src = el.get("src") or el["data"]
    rel = re.sub(r"^.*?\d{4}\.\d{4,5}(v\d+)?/", "", src)  # path inside the paper's HTML folder
    name = "figures/" + re.sub(r"[^A-Za-z0-9._-]", "_", rel)
    assets[name] = urljoin(page_url, src)
    img = new("img", src=name, alt=el.get("alt", ""), loading="lazy")
    for k in ("width", "height"):
        if el.get(k): img[k] = el[k]
    try:  # aspect ratio lets the shell scale figures to the column without making tall ones taller than the screen
        img["style"] = f"--ar:{float(el['width']) / float(el['height']):.4f}"
    except (KeyError, ValueError, ZeroDivisionError):
        pass
    el.replace_with(img)
    imgs.setdefault(name, []).append(img)
for fig in art.select("figure"):
    fig["class"] = fig.get("class", []) + ["poppable"]
    for tag in fig.select(".ltx_tag_figure, .ltx_tag_table"):
        tag["class"] = tag.get("class", []) + ["fig-label"]
for t in art.select("table.ltx_tabular"):
    wrap = new("div", ["table-scroll"]); t.wrap(wrap)

# ---- headings, cross-references, inline styles
for tag in art.select(".ltx_tag_section, .ltx_tag_appendix, .ltx_tag_subsection, .ltx_tag_subsubsection"):
    tag["class"] = tag.get("class", []) + ["section-number"]
for a in art.select("a.ltx_ref"):
    a["class"] = a.get("class", []) + (["cite-link"] if a.find_parent("cite") else ["xref"])
    a.attrs.pop("title", None)
for el in art.select("[style]"):
    if el.name != "img": del el["style"]

# ---- contents: top-level sections and their subsections
toc = ['<ul class="toc-list">']
for sec in art.select("section.ltx_section, section.ltx_appendix"):
    h = sec.find(["h2", "h1"])
    if not h or not sec.get("id"): continue
    subs = [s for s in sec.find_all("section", class_="ltx_subsection", recursive=False) if s.get("id") and s.find("h3")]
    app = " toc-appendix" if "ltx_appendix" in sec["class"] else ""
    toc.append(f'<li class="toc-group{app}"><a href="#{sec["id"]}">{text(h)}</a>')
    if subs:
        toc.append('<ul class="toc-sub">' + "".join(f'<li><a href="#{s["id"]}">{text(s.find("h3"))}</a></li>' for s in subs) + "</ul>")
    toc.append("</li>")
toc.append("</ul>")

# ---- write
OUT.mkdir(parents=True, exist_ok=True)
(OUT / "figures").mkdir(exist_ok=True)
with ThreadPoolExecutor(4) as pool:
    list(pool.map(lambda item: (OUT / item[0]).exists() or download(item[1], OUT / item[0]), assets.items()))
tones = {name: figure_tone(OUT / name)[0] for name in assets}
for name, tags in imgs.items():
    for t in tags: t["data-tone"] = tones[name]

html = fill(TITLE=title, EYEBROW=f"arXiv {version} · reading copy", BYLINE=byline, TOC="".join(toc),
            BODY=abs_html + "".join(map(str, art.contents)), ENDNOTES=fn_html + bib_html,
            EXTRA_CSS=(Path(__file__).parent / "latexml.css").read_text())
(OUT / "index.html").write_text(html, encoding="utf-8")
batches = write_batches(OUT)
n_math = len(re.findall(r"data-tex=", html))
print(f"{OUT}/index.html: {len(html) // 1024} KB, {n_math} equations, {len(assets)} images, "
      f"{len(fns)} footnotes ({sum(t == 'line' for t in tones.values())} figures inverted in dark mode); "
      f"publish in {len(batches)} batch(es)")
